scripts.酒客对话.txt:
Say("阔嘴张：老兄，你可曾上过武当山？", 0);
Say("光头李：没有，不过我听说那武当山是很难上的。", 0);
Say("阔嘴张：是呀，不瞒你说，刚才小弟我就是在武当山洗剑池被牛鼻子道士给打回来的。", 0);
Say("光头李：原来如此。唉，“少林武当，泰山北斗”，果然名不虚传！", 0);
Say("阔嘴张：要怪只能怪咱学艺不精。自从听说藏剑山庄庄主卓非凡因挑战江南梅家庄一夜成名之后，咱就不胜景仰，也想效仿一二，不想一出道就碰壁，想起来真他奶奶的不爽！", 0);
Say("光头李：数日前，在下机缘巧合，见到了那卓非凡。如能再见到武当山的<color=Red>天星道长<color=Black>，那在下便此生无憾了！", 0);
Say("阔嘴张：兄台果真见到了卓非凡？", 0);
Say("光头李：不错，那次我有事路过藏剑山庄，正好遇到卓非凡在门口送客，我在远处看了一眼，啧啧，百闻不如一见，果然是英姿飒爽，不同凡响！", 0);
Say("阔嘴张：你小子倒有些眼福啊！", 0);
PlayerGoto(8, 93);
SetPlayerDir(7);
Say("杨影枫：我正愁没有什么方法名扬天下，倒不如学学那卓非凡，武当的名头如此响亮，我不妨上<color=Red>武当山<color=Black> 走一趟。", 2);
SetNpcScript("武当山下酒客","武当山下酒客对话.txt");
Return;

scripts.强盗死亡脚本.txt:
	Add($Sub01Death, 1);
	If ($Sub01Death >= 3) @Continue;
	Return;
@Continue:
	Sleep(400);
	FadeOut();
	StopMusic();
	ClearBody();
	DelNpc("强盗头目");
	DelNpc("强盗跟班甲");
	DelNpc("强盗跟班乙");
	Say("强盗头目：弟兄们，这小子太厉害，好汉不吃眼前亏，撤！", 66);
	Say("杨影枫：看你们以后还敢不敢为非作歹！暂且放你们一条生路，以后再做坏事，小心你们的狗命！", 2);
	SetPlayerPos(10, 36);
	SetPlayerDir(3);
	SetMapTrap(1, "Trap01.txt");
	SetMapTrap(2, "Trap02.txt");
	SetMapTrap(4, "Trap04.txt");
	Assign($SubEvent01, 10);
	FadeIn();
	Say("张仲天：多谢少侠相助，在下真不知该如何答谢少侠的救命之恩。", 51);
	Say("杨影枫：区区小事，不用客气。", 2);
	Say("张仲天：在下张仲天，行商为生，不知少侠如何称呼？", 51);
	Say("杨影枫：在下杨影枫。", 2);
	Say("张仲天：原来是杨少侠，杨少侠行侠仗义，好生令人钦佩。", 51);
	Say("杨影枫：不敢当，路见不平，拔刀相助，乃是习武之人份内之事。", 2);
	Say("张仲天：杨少侠，在下要到前面的惠安镇投宿，少侠若是有空，我们到惠安镇喝酒聊天如何？", 51);
	Say("杨影枫：多谢，不过我此刻正好有事，以后有机会再到惠安镇找张大哥一叙吧。", 2);
	Say("张仲天：也好，那在下就在惠安镇等候少侠的光临啦！", 51);
	Say("杨影枫：好，后会有期。", 2);
	Say("张仲天：杨少侠，后会有期。", 51);
	Memo("解救被劫的商人张仲天。");
	NpcGoto("张仲天", 12, 43);
	NpcGoto("张仲天", 16, 53);
	DelNpc("张仲天");
	Memo("去惠安镇。");
	PlayMusic("Mc011.mp3");
	Return;

scripts.酒肆老板对话.txt:
	If ($SubEvent01 == 5) @end;

