		Say("杨影枫：好说，店家尽管开口，包在我身上。", 2);
		Say("酒肆老板：先谢过公子！这三味调料分别是野姜、草葱和罂粟，这武当山附近应该就可以找到。");
		Say("酒肆老板：烦劳公子啦。");
		Memo("帮武当山下酒肆老板寻找野姜、草葱和罂粟。");
		Assign($SubEvent02, 2);
		Goto @end;
