			Say("杨影枫：多谢！", 2);
			Goto @end;
		Goto @end;
	@Sub02Rand2:
		Say("酒肆老板：公子，你答应我的野姜、草葱和罂粟，找到没有啊？");
		Say("杨影枫：老板不要急，我还在找呢！", 2);
		Goto @end;
		
